<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
final class UnderwritingCase extends Model{use HasUuids;protected$fillable=['tenant_id','proposal_id','carrier_id','status','priority','referral_reasons','assigned_to','decision_due_at'];protected function casts():array{return['referral_reasons'=>'array','decision_due_at'=>'datetime'];}public function proposal():BelongsTo{return$this->belongsTo(Proposal::class);}public function carrier():BelongsTo{return$this->belongsTo(Carrier::class);}public function referrals():HasMany{return$this->hasMany(UnderwritingReferralTask::class);}public function decisions():HasMany{return$this->hasMany(UnderwritingDecision::class);}}
